export function settingsText(locale: AqryoLocale, source: string): string {
  const normalized = source
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase()
    .replace(/[.…:]+$/, "");
  const key = sourceKeys[normalized];
  return key ? (source.trim().startsWith("←") ? "← " : "") + SETTINGS_COPY[locale][key] : source;
}

export function settingsRecord<T extends Record<string, string>>(
  locale: AqryoLocale,
  source: T,
): { [K in keyof T]: string } {
  return Object.fromEntries(
    Object.entries(source).map(([key, value]) => [key, settingsText(locale, value)]),
  ) as { [K in keyof T]: string };
}

// Preserve the service contract while the browser confirmation follows its language.
export const DELETION_CONFIRMATION_TOKEN = "HESABIMI SİL";
export function isDeletionConfirmation(value: string, locale: AqryoLocale) {
  const normalize = (text: string) => text.normalize("NFKC").trim().toLocaleUpperCase(locale);
  return normalize(value) === normalize(SETTINGS_COPY[locale].deletePhrase);
}

export function settingsFeedback(locale: AqryoLocale, source: string): string {
  const normalized = source
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase()
    .replace(/[.…:]+$/, "");
  return sourceKeys[normalized] ? settingsText(locale, source) : SETTINGS_COPY[locale].saveError;
}
